impl Abi for crate::ported::types::WireError {
    const WORDS: usize = 2;
    fn put(&self, out: &mut [u64]) {
        match self {
            crate::ported::types::WireError::Truncated => {
                out[0] = 0;
            }
            crate::ported::types::WireError::BadDataOffset => {
                out[0] = 1;
            }
            crate::ported::types::WireError::MalformedOption { kind: f0 } => {
                out[0] = 2;
                Abi::put(f0, &mut out[1..]);
            }
            crate::ported::types::WireError::OptionsTooLong => {
                out[0] = 3;
            }
            crate::ported::types::WireError::BufferTooSmall => {
                out[0] = 4;
            }
            crate::ported::types::WireError::TooLong => {
                out[0] = 5;
            }
            crate::ported::types::WireError::BadChecksum => {
                out[0] = 6;
            }
        }
    }
    fn get(words: &[u64]) -> Self {
        match words[0] {
            0 => crate::ported::types::WireError::Truncated,
            1 => crate::ported::types::WireError::BadDataOffset,
            2 => crate::ported::types::WireError::MalformedOption { kind: Abi::get(&words[1..]) },
            3 => crate::ported::types::WireError::OptionsTooLong,
            4 => crate::ported::types::WireError::BufferTooSmall,
            5 => crate::ported::types::WireError::TooLong,
            6 => crate::ported::types::WireError::BadChecksum,
            tag => panic!("invalid WireError tag {tag} from Vesper"),
        }
    }
}

/// Owned handle of a Vesper `Tcb` value: its words, which own the Vesper
/// allocations they point to. Dropping it calls `vesper_tcp_Tcb_drop`.
pub struct Tcb {
    words: [u64; 129],
}

impl Tcb {
    /// # Safety
    /// `words` must hold a `Tcb` value of this library that the caller owns.
    unsafe fn from_words(words: &[u64]) -> Self {
        let mut owned = [0u64; 129];
        owned.copy_from_slice(&words[..129]);
        Self { words: owned }
    }

    /// A borrowed view of the value.
    pub fn as_ref(&self) -> TcbRef<'_> {
        TcbRef { words: &self.words }
    }
}

impl Drop for Tcb {
    fn drop(&mut self) {
        // SAFETY: the handle owns its words and is dropped once.
        unsafe { vesper_tcp_Tcb_drop(self.words.as_mut_ptr()) };
    }
}

impl core::fmt::Debug for Tcb {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str("Tcb { .. }")
    }
}

// SAFETY: the handle owns its Vesper allocations exclusively (no Vesper
// code keeps a reference to them), and they are plain heap memory.
unsafe impl Send for Tcb {}
// SAFETY: shared access only reads the words and the memory they own.
unsafe impl Sync for Tcb {}

